/**
 * Definition for _Node.
 * class _Node {
 *     val: boolean
 *     isLeaf: boolean
 *     topLeft: _Node | null
 *     topRight: _Node | null
 *     bottomLeft: _Node | null
 *     bottomRight: _Node | null
 *     constructor(val?: boolean, isLeaf?: boolean, topLeft?: _Node, topRight?: _Node, bottomLeft?: _Node, bottomRight?: _Node) {
 *         this.val = (val===undefined ? false : val)
 *         this.isLeaf = (isLeaf===undefined ? false : isLeaf)
 *         this.topLeft = (topLeft===undefined ? null : topLeft)
 *         this.topRight = (topRight===undefined ? null : topRight)
 *         this.bottomLeft = (bottomLeft===undefined ? null : bottomLeft)
 *         this.bottomRight = (bottomRight===undefined ? null : bottomRight)
 *     }
 * }
 */

function construct(grid: number[][]): _Node | null {
  // Строит узел для квадрата со стороной size и левым верхним углом (row, col)
  const build = (row: number, col: number, size: number): _Node => {
    // Одна клетка — всегда лист со значением этой клетки
    if (size === 1) return new _Node(grid[row][col] === 1, true);

    // Делим квадрат на четыре четверти и строим их рекурсивно
    const half = size / 2;
    const topLeft = build(row, col, half);
    const topRight = build(row, col + half, half);
    const bottomLeft = build(row + half, col, half);
    const bottomRight = build(row + half, col + half, half);

    // Все четыре четверти — листья с одинаковым значением:
    // значит, весь квадрат однородный, схлопываем его в один лист
    if (
      topLeft.isLeaf &&
      topRight.isLeaf &&
      bottomLeft.isLeaf &&
      bottomRight.isLeaf &&
      topLeft.val === topRight.val &&
      topLeft.val === bottomLeft.val &&
      topLeft.val === bottomRight.val
    ) {
      return new _Node(topLeft.val, true);
    }

    // Иначе — внутренний узел; val для него может быть любым
    return new _Node(true, false, topLeft, topRight, bottomLeft, bottomRight);
  };

  return build(0, 0, grid.length);
}

// Время: O(n²) — каждая клетка обрабатывается один раз, слияние узла за O(1)
// Память: O(log n) на рекурсию (плюс сами узлы дерева)
